def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator color fills at least one complete row and one complete column.
    sep = None
    for color in set(v for row in grid for v in row):
        if (any(all(v == color for v in row) for row in grid)
                and any(all(grid[r][c] == color for r in range(h)) for c in range(w))):
            sep = color
            break

    row_seps = [r for r, row in enumerate(grid) if all(v == sep for v in row)]
    col_seps = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def blocks(length, separators):
        bounds = [-1] + separators + [length]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_blocks = blocks(h, row_seps)
    col_blocks = blocks(w, col_seps)

    counts = {}
    for row in grid:
        for value in row:
            if value != sep:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    anomaly = next(value for value in counts if value != background)

    return [
        [
            1 if sum(grid[r][c] == anomaly
                     for r in range(r0, r1)
                     for c in range(c0, c1)) >= 2 else background
            for c0, c1 in col_blocks
        ]
        for r0, r1 in row_blocks
    ]
